files.content:
@keyframes marquee {
  0% {
    transform: translateX(120%);
  }

  100% {
    transform: translateX(-200%);
  }
}

* {
  box-sizing: border-box;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 20px 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
h2,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

.content__item:not(.banner) {
  width: 90%;
  margin: auto;
  padding: 40px;
  background-color: #fff;
}

.content__item:not(.banner) a {
  color: currentColor;
  text-decoration: none;
}

.content__item:not(.banner):hover {
  outline: 2px solid #fd24af;
}

.content__item h2 {
  margin-bottom: 20px;
  text-transform: uppercase;
}

.content__item:not(:last-child) {
  margin-bottom: 20px;
}

.banner {
  overflow: hidden;
  color: #fff;
  background-color: #fd24af;
}

.banner:hover {
  box-shadow: 0 0 10px 0 #fd24af;
}

.banner a {
  display: block;
  padding: 20px 0;
  font-size: 24px;
  animation: marquee 50s linear infinite;
  white-space: nowrap;
}
